let sys;
let hs1;
osobnik os, typek;
let start = 0;
let turnFactor = 10;

function setup() {
  colorMode(HSB, 360, 100, 100);
  createCanvas(windowWidth, windowHeight, WEBGL);
  smooth();
  fill(0);
  stroke(0);
  sys = new System();
  hs1 = new HScrollbar(20, 20, 192, 15, 2);
  background(0);
}

function draw() {
  if (start == 0){
    init();
    start = 1;
  }
  else{
    background(0);
    update();
  }
  hs1.update();
  turnFactor = abs(int(hs1.getPos()/4)-3);
  hs1.display();
  text( "Turn factor: " + (int(hs1.getPos()/4)-3), 25, 25);
	fill(102, 102, 102);
  text( "Particles: " + (int(sys.il_os)), 25, 50);
  text( "Click to add particle.", 25, 75);
}

function init(){
  for (i = 0; i < sys.start_os; i++){
		let pos = new PVector(random(width-20)+10, random(height-20)+10);
    os = new osobnik(pos.x,pos.y);
    sys.osobniki.add(os);
    os.draw();
  }
}  

function update(){
   for (i = 0; i < sys.osobniki.size(); i++){
     typek = (osobnik) sys.osobniki.get(i);
       typek.update();
       typek.draw();
   }
}

function mouseClicked() {
    os = new osobnik((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    sys.osobniki.add(os);
    os.draw();  
}

class System {
  start_os = 10;
  max_os = 50;
  il_os = 0;
  max_szybk = 200;
  min_szybk = 1;
  osobniki;

  constructor(){
    osobniki = new ArrayList();
  }
}

class osobnik extends System{
  nr;
  wlk;
  sas, cz_sas;
  spd;
  poz, acc;
  kolor;


  constructor(x, y){
    this.nr = sys.il_os;
    sys.il_os = this.nr+1;
    this.wlk=10;
    poz = new PVector(x, y);
    spd = new PVector(random(2), random(2));
    this.kolor = color(random(320, 420) % 360, 90, 100);
    this.acc = new PVector();
  }

 function update(){
/*    if (poz.x > width || poz.x < 0) {
      spd.x *= -0.9;
    }
    if (poz.y < 0 || poz.y > height ) {
      spd.y *= -0.9;
    }*/
   if (poz.x > width) {
	    poz.x = 0;
   }
   if (poz.y > height ) {
     poz.y = 0;
   }
   if (poz.x < 0) {
     poz.x = width;
   }
   if (poz.y < 0) {
     poz.y = height;
   }
   this.sas = 0;
   this.cz_sas = 0;
   let dyst = 150;
   for (i = 0; i < sys.osobniki.size(); i++){
     osobnik inny = (osobnik) sys.osobniki.get(i);
     if (this.nr != inny.nr){
       let d = PVector.dist(this.poz,inny.poz);
       if (d < dyst){
         dyst = d;
         this.sas = i;
         this.cz_sas = 1;
       }
     }
   }
   if (this.cz_sas > 0){
     osobnik sasiad = (osobnik) sys.osobniki.get(this.sas);
     var d = PVector.dist(this.poz,sasiad.poz);
     if (d < wlk){
	     spd.x *= random(50);
	     spd.y *= random(50);
     }
       let attraction = new PVector(sasiad.poz.x, sasiad.poz.y);
       attraction.sub(this.poz);
       this.acc.set(attraction);
       this.acc.normalize();
       this.acc.div(turnFactor);
       spd.add(this.acc);
       spd.limit(max_szybk * (1/60));
   }
   poz.add(spd);
 }

  function draw(){
    pushMatrix();
    stroke(this.kolor);
    fill(this.kolor);
    strokeWeight(2);
    ellipse(this.poz.x,this.poz.y,this.wlk,this.wlk);
    if (this.cz_sas > 0){
      osobnik sasiad = (osobnik) sys.osobniki.get(this.sas);
      let l = PVector.sub(sasiad.poz,this.poz);
      line(sasiad.poz.x, sasiad.poz.y, poz.x, poz.y);
    }
    popMatrix();
 }

}

